/**
This is a simple guide illustrating some common API calls used in algorithm animation programs.
Programs are written in JavaScript. You can usually implement an algorithm in JavaScript
and add animation effects using API calls.
For more details, see the examples and the User Guide at
https://docs.google.com/document/d/1FEi-RJ97UxsDuxHQrGmyOUanNWrWdq84NKicSdswGDY
 */

// Assume the graph has node "1" and edge "1,2" - weighted_7 is an example.
// Any string can be used as a node Id; an edge id is a string of the form "node1,node2".
// If the graph is undirected, the edge "1,2" is the same as "2,1".
const node = "1";
const edge = "1,2";

// Some common API calls for algorithm animation programs:
color(node, "yellow");  // Change the color of a node to yellow
setWeight(edge, 5);     // Set the weight of an edge to 5
label(node, "A");    // Set the label of a node to "A"
highlight(edge);        // Highlight an edge, i.e., make it thicker

// Do something for each outgoing edge from a given node
for ( const edge of outgoing(node) ) {
    // Do something with the edge, for example:
    highlight(edge);  // Highlight the edge
    // Do something with the other end of the edge
    const otherNode = other(node, edge);
    color(otherNode, "blue");       // Change the color of the other end node to blue
}

// Specify that a set of animation effects should be executed in a single step, i.e., simultaneously
step(() => {
    color(node, "green");                       // Change the color of a node to green
    setShape(node, "star");                     // Change the shape of a node to a star
    display(`Node ${node} has been visited`);   // Display a message
});

// Apply an effect to all nodes in the graph, typically at the start of an algorithm
// Similar API calls exist for other attributes and for edges.
hideAllNodeWeights();

/**
 * Breadth first search on a graph; works for both directed and undirected graphs.
 */
// Queue of nodes to visit
let queue = [];
// Number of steps taken
let time = 0;

// Adds a node to the queue
function queueNode(node, weight) {
    queue.push(node);
    step(() => {
        display(`queueing node ${node}, queue = [${queue}]`)
        highlight(node);
        setWeight(node, weight);
        label(node, "#" + time++);
    })
    print(`Queued node '${node}'`);
}

step(() => { // Initialize with start node
    clearNodeMarks();
    clearNodeHighlights();
    clearNodeLabels();
    clearNodeWeights();

    clearEdgeHighlights();
    clearEdgeColors();

    const start = promptNode("Enter start node:");
    queueNode(start, 0);
    print(`Starting at node '${start}'`);
});

while ( queue.length > 0 ) {
    const current = queue.shift();
    step(() => { // Visit node
        display(`visiting node ${current}, queue = [${queue}]`)
        display("Queue: " + queue);
        mark(current);
    });

    for ( const edge of outgoing(current) ) {
        const next = other(current, edge);

// !!! avoid steps within steps
//        step(() => { // Check outgoing edges
            print(`Checking edge '${edge}'`);
            if ( ! hasColor(edge) ) { // never seen this edge, only relevant for undirected
                if ( highlighted(next) ) { // already visited node
                    color(edge, "red");
                }
                else { // have not visited node
                    queueNode(next, weight(current) + 1);
                    step(() => {
                        color(edge, "blue");
                        highlight(edge)
                    })
                }
            }
//        });
    }
}
display("Algorithm finished: all reachable nodes have been visited")

/**
 * Depth first search: works for both undirected and directed graphs.
 */

// time at which each node is discovered
let discoveryTimes = {};
// time at which each node has finished being explored
let finishTimes = {};
// Number of steps taken
let time = 1;

print("dfs");
step(() => {
    clearNodeMarks();
    clearNodeHighlights();
    clearNodeLabels();
    clearNodeWeights();
    clearEdgeHighlights();
    clearEdgeColors();
    clearEdgeLabels();
    hideAllEdgeWeights();
})

// let user choose another starting node if there are remaining unreachable nodes
let unvisited = new Set(getNodes());
while ( unvisited.size > 0 ) {
    const start = promptNodeFrom("Enter start node:", unvisited);
    visit(start);
}

function visit(node) {
    unvisited.delete(node);
    display(`visit ${node}`);
    step(() => {
        discoveryTimes[node] = time++;

        mark(node);
        label(node, discoveryTimes[node]);
    });

     for ( const edge of outgoing(node) ) {
        if ( hasColor(edge) ) continue; // seen this edge from the other end (undirected)
           const nextNode = other(node, edge);
            if ( hasLabel(edge) ) {
                continue;
            }

        step(() => {
            if ( ! marked(nextNode) ) { // not yet visited
                highlight(edge);
                color(edge, "blue");
                highlight(nextNode);
            } else if ( finishTimes[nextNode] == null ) { // ancestor
                label(edge, "B");
                color(edge, "red");
            } else if ( finishTimes[nextNode] > discoveryTimes[node] ) { // descendant
                label(edge, "F");
                color(edge, "green");
            } else {
                label(edge, "C");
                color(edge, "orange");
            }
        });
        // keep the recursive call outside of the step
        if ( ! marked(nextNode) ) { // not yet visited
            visit(nextNode);
        }
    }

    finishTimes[node] = time++;
    label(node, discoveryTimes[node] + "/" + finishTimes[node]);
}

/**
 * Depth first search for directed graphs, followed by a reverse DFS that identifies strongly connected components.
 * Try it out on the graph g-12.
 */

// time at which each node is discovered
let discoveryTimes = {};
// time at which each node has finished being explored
let finishTimes = {};
// used as a stack for visited nodes
//  - push when visit to a node is finished
//  - pop when nodes are visited in reverse order for strong components phase
let finished = [];
// Number of steps taken
let time = 1;
// component of a node or edge
let element_component = {}

/**
 * rotation of colors to use for components
 */
const component_color = ['brown', 'blue', 'red', 'violet', 'green', 'cyan', 'magenta', 'yellow', 'gray']

/**
 * sets the component of the element (node or edge) and colors it;
 *  the component is used as a label and displayed
 */
function color_component(element, component) {
    step(() => {
        display(`component for ${element} is ${component}`)
        const color_index = component % component_color.length
        color(element, component_color[color_index])
        highlight(element)
        label(element, component)
    })
}

function set_component(element, component) {
    element_component[element] = component
}

function get_component(element) {
    return element_component[element]
}

function has_component(element) {
    return element in element_component
}

setDirected(true)
step(() => {
    clearNodeMarks();
    clearNodeHighlights();
    clearNodeLabels();
    clearNodeWeights()
    clearEdgeHighlights();
    clearEdgeColors();
    clearEdgeLabels();
    clearEdgeWeights();
})

/********** Main algorithm starts here ************/

// let user choose another starting node if there are remaining unreachable nodes
let unvisited = new Set(getNodes());
while ( unvisited.size > 0 ) {
    let start = promptNodeFrom("Enter start node:", unvisited);
    visit(start);
}

step(() => {
    clearEdgeLabels()
    clearNodeLabels()
    clearNodeMarks()
    clearEdgeHighlights()
    clearEdgeColors()
})

display("Start reverse dfs")
let component = 1
while ( finished.length > 0 ) {
    const node = finished.pop()
    if ( ! has_component(node) ) {
        reverse_visit(node, component)
        component++
    }
}
display("Algorithm finished: Nodes in their components based on their colors")

/********** vist functions ****************/

function visit(node) {
    display(`visit ${node}`);
    unvisited.delete(node);
    step(() => {
        discoveryTimes[node] = time++;
        mark(node);
        label(node, discoveryTimes[node]);
    });

     for ( const edge of outgoing(node) ) {
        const nextNode = other(node, edge);
        display(`considering neighbor ${nextNode}`)
        if ( ! marked(nextNode) ) { // not yet visited
            step(() => {
                display(`node ${nextNode} has not been visited`)
                highlight(edge);
                color(edge, "blue");
                highlight(nextNode);
            })
            visit(nextNode);
        } else if ( finishTimes[nextNode] == null ) { // ancestor
            step(() => {
                label(edge, "B");
                color(edge, "red");
            })
        } else if ( finishTimes[nextNode] > discoveryTimes[node] ) { // descendant
            step(() => {
                label(edge, "F");
                color(edge, "green");
            })
        } else {
            step(() => {
                label(edge, "C");
                color(edge, "orange");
            })
        }
    }
    finishTimes[node] = time++;
    label(node, discoveryTimes[node] + "/" + finishTimes[node]);
    finished.push(node);
}

/**
 * visit the node and check its incoming rather than outgoing neighbors
 * component is an integer denoting the current component number:
 *  also used to decide on a color for the component
 * here, we no longer care about discovery/finish times or types of edges
 */
function reverse_visit(node, component) {
    // do animation first, logic later
    display(`reverse visiting node ${node}`)
    step(() => {
        color_component(node, component)
        for ( const in_edge of incoming(node) ) {
            display(`incoming edge is ${in_edge}`)
            const neighbor = other(node, in_edge)
            if ( ! has_component(neighbor) ) {
                color_component(neighbor, component)
                color_component(in_edge, component)
            }
            else if ( component == get_component(neighbor) ) {
                color_component(in_edge, component)
            }
        }
    })
    // separating logic from animation
    set_component(node, component)
    for ( const in_edge of incoming(node) ) {
        const neighbor = other(node, in_edge)
        if ( ! has_component(neighbor) ) {
            set_component(neighbor, component)
            reverse_visit(neighbor, component)
        }
    }
}

/**
 * an implementation of Dijkstra's algorithm
 * edges turn yellow when being explored, then
 *  - red if other end seen for the first time
 *  - green if relax yields improvement
 *  - blue when edge becomes part of the tree
 */


let predecessorEdge = {}    // edge currently leading to shortest path
let nodePQ = {}             // priority queue of nodes, key is node, value is weight
let inTree = {}             // true if a node is in the shortest paths tree

/**
 * Needed to check if queue is empty - must be a better way
 */
function PQsize() {
    return Object.keys(nodePQ).length
}

/**
 * uses a linear search of the queue
 * @returns node with minimum weight
 */
function removeMin() {
    let min_weight = Infinity
    let min_node = null
    for ( const node in nodePQ ) {
        const weight = nodePQ[node]
        if ( weight < min_weight ) {
            min_weight = weight
            min_node = node
        }
    }
    delete nodePQ[min_node]
    return min_node
}

/**
 * @return the average weight of the edges, ignoring edges with no weight,
 * and those with non-positive weight.
 * if there are no edges with positive weight, returns 1
 */
function averageWeight() {
    let totalWeight = 0;
    let count = 0;
    for ( const edge of getEdges() ) {
        if ( hasWeight(edge) && weight(edge) > 0 ) {
            totalWeight += weight(edge);
            count++;
        }
    }
    return count > 0 ? totalWeight / count : 1;
}

step(() => {
    clearNodeMarks();
    hideAllNodeWeights();
    clearNodeColors();
    clearNodeShapes();

    clearEdgeColors();
    clearEdgeHighlights();

    for ( const edge of getEdges() ) {
        if ( ! hasWeight(edge) ) {
            const weight = averageWeight()
            display(`*** edge ${edge} has no weight, setting to average weight ${weight} ***`)
            setWeight(edge, weight)
        }
    }

    for ( const node of getNodes() ) {
        nodePQ[node] = Infinity
        setWeight(node, Infinity)
    }
})

let start_node = promptNode("Enter starting node:", "invalid node ${start_node}");
setWeight(start_node, 0)
showWeight(start_node)
nodePQ[start_node] = 0

while ( PQsize() > 0 ) {
    const current_node = removeMin()
    inTree[current_node] = true
    if ( ! current_node ) {
        display("*** there are unreachable nodes ***")
        break
    }
    print(current_node)
    step(() => {
        color(current_node, "yellow");
        setShape(current_node, "star")
        if ( predecessorEdge[current_node] ) {
            color(predecessorEdge[current_node], "blue")
            setEdgeWidth(predecessorEdge[current_node], 6)
            display(`node ${current_node} added
                     with predecessor ${other(current_node, predecessorEdge[current_node])}`)
        }
    })

    const current_dist = weight(current_node)
    for ( const edge of outgoing(current_node) ) {
        const next_node = other(current_node, edge)
        if ( inTree[next_node ] ) continue
        showWeight(next_node)
        const next_dist = current_dist + weight(edge)
        print(next_node + " " + next_dist)
        color(edge, "violet")
        if ( next_dist < weight(next_node) ) {
            step(() => {
                if ( predecessorEdge[next_node] ) {
                    color(predecessorEdge[next_node], "yellow")
                    color(edge, "green")
                    setEdgeWidth(edge, 4)
                    display(`relax ${edge} updated distance of ${next_node} to ${next_dist}`)
                }
                else {
                    color(edge, "red")
                }
                predecessorEdge[next_node] = edge
                setWeight(next_node, next_dist)
                nodePQ[next_node] = next_dist
            })
        }
        else {
            uncolor(edge)
        }
    }
}
display("Algorithm finished: all reachable nodes have been visited")

/**
 * Like Dijkstra's algorithm: takes both a start node and a destination; uses an a-star search
 *  that incorporates the Euclidian distance between each node and the destination.
 * Usually visits far fewer nodes than Dijkstra's algorithm, because it focuses
 * on the nodes that are closer to the destination.
 */

 const START_COLOR = "cyan"
 const END_COLOR = "magenta"
 const DEFAULT_COLOR = "yellow"

let predecessorEdge = {}    // edge currently leading to shortest path
let nodePQ = {}             // priority queue of nodes, key is node, value is weight
let destDist = {}           // distance of each node to the destination
let inTree = {}             // true if a node is in the shortest paths tree

/**
 * Needed to check if queue is empty - must be a better way
 */
function PQsize() {
    return Object.keys(nodePQ).length
}

/**
 * uses a linear search of the queue
 * @returns node with minimum weight
 */
function removeMin() {
    let min_weight = Infinity
    let min_node = null
    for ( const node in nodePQ ) {
        const weight = nodePQ[node]
        if ( weight < min_weight ) {
            min_weight = weight
            min_node = node
        }
    }
    delete nodePQ[min_node]
    return min_node
}

function distance(node1, node2) {
    const x1 = getX(node1)
    const x2 = getX(node2)
    const y1 = getY(node1)
    const y2 = getY(node2)
    const xdiff = x1 - x2
    const ydiff = y1 - y2
    return Math.sqrt(xdiff * xdiff + ydiff * ydiff)
}

step(() => {
    setDirected(false);
    clearNodeMarks();
    hideAllNodeWeights();
    clearNodeColors();
    clearNodeShapes();

    clearEdgeColors();
    clearEdgeHighlights();

    for ( const edge of getEdges() ) {
        setWeight(edge, distance(source(edge), target(edge)))
        showEdgeWeight(edge)
    }

    for ( const node of getNodes() ) {
        nodePQ[node] = Infinity
        setWeight(node, Infinity)
    }
})

const start = promptNode("Enter starting node:", "invalid node ${start}");
const destination = promptNode("Enter destination node:", "invalid node ${destination}");
step(() => {
    color(start, START_COLOR)
    color(destination, END_COLOR)
})
for ( const node of getNodes() ) {
    destDist[node] = distance(node, destination)
}

step(() => {
    setWeight(start, destDist[start])
    showWeight(start)
})
nodePQ[start] = destDist[start]

let destination_reached = false
while ( PQsize() > 0 ) {
    const current_node = removeMin()
    inTree[current_node] = true
    if ( ! current_node ) {
        display("*** there are unreachable nodes ***")
        break
    }
    step(() => {
        if ( current_node == start ) {
            color(current_node, START_COLOR)
        } else if ( current_node == destination ) {
            color(current_node, END_COLOR)
        } else {
            color(current_node, DEFAULT_COLOR);
        }
        setShape(current_node, "star")
        if ( predecessorEdge[current_node] ) {
            color(predecessorEdge[current_node], "blue")
            setEdgeWidth(predecessorEdge[current_node], 6)
            display(`node ${current_node} added
                     with predecessor ${other(current_node, predecessorEdge[current_node])}`)
        }
    })

    if ( current_node == destination ) {
        display(`destination ${current_node} reached`)
        destination_reached = true
        break
    }

    for ( const edge of outgoing(current_node) ) {
        const next_node = other(current_node, edge)
        if ( inTree[next_node ] ) continue
        showWeight(next_node)
        const new_weight = weight(current_node) + weight(edge) + destDist[next_node] - destDist[current_node]
        color(edge, "violet")
        if ( new_weight < weight(next_node) ) {
            step(() => {
                if ( predecessorEdge[next_node] ) {
                    color(predecessorEdge[next_node], "yellow")
                    color(edge, "green")
                    setEdgeWidth(edge, 4)
                    display(`relax ${edge} updated weight for ${next_node}`)
                }
                else {
                    color(edge, "red")
                }
                predecessorEdge[next_node] = edge
                setWeight(next_node, new_weight)
                nodePQ[next_node] = new_weight
            })
        }
        else {
            uncolor(edge)
        }
    }
}
if ( ! destination_reached ) {
        display("All reachable nodes have been visited, but destination has not been found")
}

/**
 * animation of Kruskal's minimum spanning tree algorithm
 */

let parent = {}     // parent pointers for disjoint set structure

function initDisjointSets() {
    for ( const node of getNodes() ) {
        parent[node] = node
    }
}

function findSet(node) {
    print(`-> findSet, node = ${node}, parent = ${parent[node]}`)
    if ( node != parent[node] ) {
        parent[node] = findSet(parent[node])
    }
    print(`<- findSet, node = ${node}, parent = ${parent[node]}`)
    return parent[node]
}

function link(node_1, node_2) {
    print(`-> link ${node_1} ${node_2}`)
    parent[node_1] = node_2
    print(`<- link ${node_1} ${node_2} ${parent[node_1]}`)
}

function union(node_1, node_2) {
    link(findSet(node_1), findSet(node_2))
}

step(() => {
    clearNodeMarks();
    clearNodeWeights();
    clearEdgeColors();

    for ( const edge of getEdges() ) {
        if ( ! hasWeight(edge) ) {
            // setWeight(edge, euclidian(edge));
            display(`*** edge ${edge} has no weight, setting to 1 ***`)
            setWeight(edge, 1)
        }
    }
})

function byWeight(edge_1, edge_2) {
    return weight(edge_1) - weight(edge_2)
}

initDisjointSets()
let edgeList = getEdges()
edgeList.sort(byWeight)
let totalWeight = 0
let numForestEdges = 0
const numNodes = getNodes().length

for ( const edge of edgeList ) {
    const s = source(edge)
    const t = target(edge)
    step(() => {
        color(edge, "red")
        setShape(s, "star")
        setShape(t, "star")
        color(s, "yellow")
        color(t, "yellow")
    })
    step(() => {
        if ( findSet(s) == findSet(t) ) {
            color(edge, "yellow")
            hideEdgeWeight(edge)
            display(`endpoints ${s} and ${t} are already connected`)
        }
        else {
            color(edge, "blue")
            highlight(edge)
            totalWeight += weight(edge)
            numForestEdges++
            union(s, t)
            display(`current forest has weight ${totalWeight}`)
        }
        setShape(s, "ellipse")
        setShape(t, "ellipse")
        color(s, "white")
        color(t, "white")
    })
    if ( numForestEdges == numNodes - 1 ) break
}
display(`--- Done, totalWeight = ${totalWeight}`)

/**
 * An implementation of the Prim-Jarnik minimum spanning tree algorithm;
 * this an almost exact copy of Dijkstra's shortest path algorithm
 * with only one difference: node weights are distances to the closest node in the tree
 * rather than distances from the start node
 */


let predecessorEdge = {}    // edge currently leading to shortest path
let nodePQ = {}             // priority queue of nodes, key is node, value is weight
let inTree = {}             // true if a node is in the shortest paths tree

/**
 * Needed to check if queue is empty - must be a better way
 */
function PQsize() {
    return Object.keys(nodePQ).length
}

/**
 * This does not work - node_map is undefined, probably have to import something
 * @param edge edge whose Euclidian distance is to be calculated 
 * @returns distance between endpoints of the edge
 */
function euclidian(edge) {
    const x_1 = node_map[source(edge)]['x']
    const y_1 = node_map[source(edge)]['y']
    const x_2 = node_map[target(edge)]['x']
    const y_2 = node_map[target(edge)]['y']
    const diff_x = x_1 - x_2
    const diff_y = y_1 - y_2
    return Math.sqrt(diff_x * diff_x + diff_y * diff_y)
}

/**
 * uses a linear search of the queue
 * @returns node with minimum weight
 */
function removeMin() {
    let min_weight = Infinity
    let min_node = null
    for ( const node in nodePQ ) {
        const weight = nodePQ[node]
        if ( weight < min_weight ) {
            min_weight = weight
            min_node = node
        }
    }
    delete nodePQ[min_node]
    return min_node
}

step(() => {
    clearNodeMarks();
    clearNodeWeights();

    clearEdgeColors();

    for ( const edge of getEdges() ) {
        if ( ! hasWeight(edge) ) {
            display("*** edge ${edge} has no weight, setting to 1, Euclidian distance does not work ***")
            setWeight(edge, 1)
        }
    }

    for ( const node of getNodes() ) {
        nodePQ[node] = Infinity
        setWeight(node, Infinity)
    }
})

const start_node = promptNode("Enter starting node:", "invalid node ${start_node}");
setWeight(start_node, 0)
nodePQ[start_node] = 0

let total_weight = 0

while ( PQsize() > 0 ) {
    const current_node = removeMin()
    inTree[current_node] = true
    if ( ! current_node ) {
        display("*** there are unreachable nodes ***")
    }
    print(current_node)
    step(() => {
        color(current_node, "yellow");
        setShape(current_node, "star")
        if ( predecessorEdge[current_node] ) {
            color(predecessorEdge[current_node], "blue")
            setEdgeWidth(predecessorEdge[current_node], 6)
            total_weight += weight(predecessorEdge[current_node])
            display(`added edge ${predecessorEdge[current_node]}, total_weight = ${total_weight}`)
        }
    })

    for (const edge of outgoing(current_node) ) {
        const next_node = other(current_node, edge)
        if ( inTree[next_node ]) continue
        const next_dist = weight(edge)
        print(next_node + " " + next_dist)
        color(edge, "violet")
        if ( next_dist < weight(next_node) ) {
            step(() => {
                if ( predecessorEdge[next_node] ) {
                    color(predecessorEdge[next_node], "yellow")
                    color(edge, "green")
                    setEdgeWidth(edge, 4)
                }
                else {
                    color(edge, "red")
                }
                predecessorEdge[next_node] = edge
                setWeight(next_node, next_dist)
                nodePQ[next_node] = next_dist
            })
        }
        else {
            uncolor(edge)
        }
    }
}
display(`Done: MST with weight ${total_weight} found for component reachable from start node`)

/**
 * Post-order traversal algorithm for trees. Works for trees only (extension .tree)
 */

setDirected(true);
let start;
let traversal = "";

// Prompts the user for a starting node
step(() => {
  clearNodeMarks();
  clearNodeHighlights();
  clearNodeLabels();
  clearNodeWeights();

  clearEdgeHighlights();
  clearEdgeColors();

  start = promptNode("Enter start node:");
  display(`Starting at node '${start}'`);
});

// Recursivly goes through the tree
function postOrder(node) {
  if (node === undefined) {
    return;
  }

  mark(node);

  // Visit all children
  for ( const x of getChildren(node) ) {
    postOrder(x);
  }

  step(() => {
    color(node, "red");
    traversal = traversal + node + " ";
    // Lists the order the nodes have been traversed in
    display(`Traversal: ${traversal}`);
  });
}

// Starts postOrder traversal on the given node
postOrder(start);

// Outputs the final traversal after algorithm is finished
display(`Algorithm finished: Final traversal: ${traversal}`);

/**
 * Pre-order traversal algorithm for trees. Works for trees only (extension .tree)
 */

setDirected(true);
let start;
let traversal = "";

// Prompts the user for a starting node
step(() => {
  clearNodeMarks();
  clearNodeHighlights();
  clearNodeLabels();
  clearNodeWeights();

  clearEdgeHighlights();
  clearEdgeColors();

  start = promptNode("Enter start node:");
  display(`Starting at node '${start}'`);
});

// Recursivly goes through the tree
function preOrder(node) {
  if (node === undefined) {
    return;
  }

  mark(node);

  step(() => {
    color(node, "red");
    traversal = traversal + node + " ";
    // Lists the order the nodes have been traversed in
    display(`Traversal: ${traversal}`);
  });

  // Visit all children
  for ( const x of getChildren(node) ) {
    preOrder(x);
  }
}

// Starts preOrder traversal on the given node
preOrder(start);

// Outputs the final traversal after algorithm is finished
display(`Algorithm finished: Final traversal: ${traversal}`);

/**
Allows the user to create a binary search tree with numerical keys using a series of prompts.
Start with empty.tree or bs-example.tree (for testing deletion)
*/

/**
The user will be prompted to enter a number -->
   - If the number is positive, it is added to the tree
   - If the number is negative, it is deleted from the tree
   - If the number is 0, the algorithm stops
Note that duplicate numbers are not allowed in this BST, although it would be
relatively easy to modify the code to allow duplicates.

Unlike many textbook descriptions, this animation uses dummy nodes only to ensure correct display.
A node has at most one dummy child. Thus, there are these cases for non-dummy nodes:
  - node is a leaf; it has no children, *not* two dummy children as in the textbooks
  - node has one real child and one dummy child
  - node has two real children
*/

/**
 * Gets rid of all markings and highlights in the tree, so that the next operation
 * can start fresh
 */
function cleanTree(){
  step(() => {
    clearNodeMarks();
    clearNodeHighlights();
    clearEdgeHighlights();
    clearEdgeColors();
  });
}

/**
 * Used to highlight the path taken to find a node
 * @param nodeId the node to accent
 */
function accentNode(nodeId) {
  color(nodeId, "orange")
}

function unaccent(nodeId) {
  uncolor(nodeId)
}

/**
 * @returns the sibling of the given node
 * @param node the node whose sibling we are finding
 * @assume the node has a parent
 * 
 * @todo add this to Thread.js and TreeInterface.js
 */
function getSibling(node) {
  if ( node === null || node === undefined ) {
    throw new Error(`getSibling called on nonexistent node`);  }
  const parent = getParent(node);
  if ( parent === null || parent === undefined ) {
    throw new Error(`getSibling called on node with ${node}, weight ${weight(node)}, no parent`);
  }
  return getLeft(parent) === node ? getRight(parent) : getLeft(parent);
}

/**
 * checks if a node is a dummy node
 * need to check that the node exists first, since this may be called
 * for a left or right child that does not exist
 * @param nodeId (id of) the node to check
 */
function isDummy(nodeId) {
  if ( nodeId === null || nodeId === undefined ) {
    return false;
  }
  return getAttribute(nodeId, "dummy");
}

// this is sort of superfluous but makes the code more readable
function dummify(nodeId) {
  setAttribute(nodeId, "dummy", true);
}

/**
 * replaces a dummy node with a real node with given weight
 * @param nodeId (id of) the dummy node to replace
 * @param weight the weight of the new node
 */
function undummify(nodeId, weight) {
  step(() => {
    setAttribute(nodeId, "dummy", false);
    setWeight(nodeId, weight);
    setAttribute(nodeId, "weightInNode", true);
    hideWeight(nodeId);
    display(`Added node with weight ${weight}`)
  });
  return nodeId;
}

/**
 * @returns a new (newly created)dummy node
 */
function createDummy(){
  const dummy = addNode()
  setAttribute(dummy, "dummy", true);
  return dummy;
}

//------------------ ADD -------------------

/**
 * Adds a node with weight k to the BST rooted at x
 * @param x a subroot of BST, initially the root of the BST
 * @param k the weight of the node to add
 */
function addNodeBST(x, k) {
  const theWeight = (x === null || x === undefined) ? null : weight(x);
  console.log(`*** -> addNodeBST x = ${x}, weight(x) =  ${theWeight}, dummy? ${isDummy(x)}, k = ${k}`);
  // If empty, make new root
  if ( x === null || x === undefined ) {
    step(() => {
      const newNode = addNode();
      setWeight(newNode, k);
      display(`Created root with weight ${k}`);
    })
    return;
  }

  accentNode(x)

  // Found duplicate node
  if ( k === weight(x) ) {
    display(`Node with key ${k} already exists`);
    return;
  }

  // If a leaf, then add new node and a dummy here
  if ( isLeaf(x) ) {
    if ( isDummy(x) ) {
      undummify(x, k)
      unaccent(x)
      return x
    } 
    step(() => {
      const newNode = addNode();
      setWeight(newNode, k);
      const dummy = createDummy();
      addEdge(x, newNode);
      addEdge(x, dummy)
      if ( k < weight(x) ) {
        setChildren(x, [newNode, dummy])
      } else {
        setChildren(x, [dummy, newNode])
      } 
      display(`Added node with weight ${k}`)
    });
    unaccent(x)
    return;
  }

  // Not a leaf, keep searching
  console.log(`Not a leaf, key ${k} at subroot with key ${weight(x)}`);
  if ( k < weight(x) ) {
    unaccent(x)
    return addNodeBST(getLeft(x), k);
  } else {
    unaccent(x)
    return addNodeBST(getRight(x), k);
  }
}

