        hideNode(next_node)
        hideNodeWeight(next_node)
        // put next_node into cover
        cover.add(next_node)
        cover_size += 1
        display("cover size = " + cover_size)
    })
} // while nodePQ not empty
step(() => {
    showAllNodes()
    checkCover()
})

/**
 * A greedy heuristic for packing.
 * A packing is a partition of vertices into sets consisting of a vertex and its neighbors.
 * Greedy means that lowest degree vertices are packed first (degree is updated dynamically).
 */
let nodePQ = {}             // priority queue of nodes, key is node, value is weight
let packing = new Set()       // set of nodes in the vertex cover

/**
 * @todo implement priority queue and functions such as degree() inside Galant; look in Thread.js 
 */

function degree(node) {
    let deg = 0
    for ( const edge of outgoing(node) ) {
        deg += 1
    }
    return deg
}

/**
 * @todo implement this in Galant
 */
function showAllNodes() {
    for ( const node of getNodes() ) {
        showNode(node)
    }
}

/**
 * Needed to check if queue is empty - must be a better way
 */
function PQsize() {
    return Object.keys(nodePQ).length
}

/**
 * uses a linear search of the queue
 * @return node with minimum weight, so lowest degree
 */
function removeMin() {
    let min_weight = Infinity
    let min_node = null
    for ( const node in nodePQ ) {
        const weight = nodePQ[node]
        if ( weight < min_weight ) {
            min_weight = weight
            min_node = node
        }
    }
    delete nodePQ[min_node]
    return min_node
}

function queueAllNodes() {
    step(() => {
        for ( const node of getNodes() ) {
            setWeight(node, degree(node))
            nodePQ[node] = degree(node)
        }
    })
}

step(() => {
    clearNodeMarks();
    clearNodeWeights();
    clearEdgeColors();
    hideAllEdgeWeights();
    //hideAllEdgeLabels(); needs to be added in Thread.js
})
display("queueing nodes")

queueAllNodes()

let packing_size = 0

while ( PQsize() > 0 ) {
    const next_node = removeMin()
    step(() => {
        highlight(next_node)
        hideNodeWeight(next_node)
        display("adding node " + next_node)
        color(next_node, "yellow")
        setShape(next_node, "star")
    })
    step(() => {
        for ( const edge of outgoing(next_node) ) {
            color(edge, "green")
            setEdgeWidth(edge, 5)
            const neighbor = other(next_node, edge)
            hideNodeWeight(neighbor)
            color(neighbor, "green")
            delete nodePQ[neighbor]
            for ( const cousin_edge of outgoing(neighbor) ) {
                const cousin = other(neighbor, cousin_edge)
                if ( cousin !== next_node ) {
                    color(cousin_edge, "yellow")
                }
                // cousins cannot be used as central nodes of a hyperedge
                // for the remainder of the packing
                hideNodeWeight(cousin)
                if ( nodePQ[cousin] ) {
                    color(cousin, "red")
                    delete nodePQ[cousin]
                }
            }
        }
    })
    // put next_node into packing
    packing.add(next_node)
    packing_size += 1
    display("packing size = " + packing_size)
} // while nodePQ not empty
display("Done: all nodes have been packed into edge-disjoint sets, packing size = " + packing_size)

/**
 * A layered graph algorithm with one step. It simply reports all measures:
 *  - total number of edge crossings
 *  - bottleneck crossings = maximum number of crossings for any edge
 *  - nonverticality = total amount by which edges deviate from vertical
 *  - bottleneck verticality = maximum amount of deviation for any edge
 *  - deviation of edge vw = (x-coord(v) - x-coord(w))^2
 */
const total = totalCrossings()
const bottleneck = bottleneckCrossings()
const nonverticality =  totalNonVerticality()
const bottleneck_verticality = bottleneckVerticality()
display(`total crossings = ${total}, bottleneck crossings = ${bottleneck}
    , nonverticality = ${nonverticality}
    , bottleneck verticality = ${bottleneck_verticality}`)

/**
 * The barycenter heuristic attempts to minimize edge crossings in layered graphs
 */
let minCrossings = 100000000;
let edgeCrossings = 0;
let minEdgeCrossings = 100000000;
let iteration = 0;
let pass = 0;
let minIteration = 0;
let minPass = 0;
let minBottleneckIteration = 0;
let minBottleneckPass = 0;
const numLayers = numberOfLayers();
let savedPositions = copyNodePositions();
let savedBottleneckPositions = copyNodePositions();

/**
 * writes a message about current number of crossings, along with context information
 */
function displayMessage( layer, sweepDirection ) {
    const crossings = totalCrossings();
    display( `pass = ${pass}, iteration = ${iteration}, layer = ${layer}, direction = ${sweepDirection}, crossings = ${crossings}, min = ${minCrossings}, bottleneck = ${edgeCrossings}, min = ${minEdgeCrossings}`);
};

/**
 * displays weights, highlighting, and message; the beginStep that
 * corresponds to the endStep here occurred when weights and highlighting
 * were undone (reset) for the previous layer
 *
 * @param weightDirection direction of layer on which the current weight
 * assignment is based 
 */
function displayAfterWeightAssignment( layer, sweepDirection ) {
    setLayerProperty(layer, "color", "cyan");
    setLayerProperty(layer, "weightHidden", false);
    if (sweepDirection == "up" ) {
        setChannelProperty(layer - 1, "color", "blue");
        setLayerProperty(layer - 1, "weightHidden", false)
    }
    else if (sweepDirection == "down" ) {
        setChannelProperty(layer, "color", "blue");
        setLayerProperty(layer + 1, "weightHidden", false)
    }
    displayMessage( layer, sweepDirection )
}

/**
 * displays state of affairs after layer is sorted and begins a step that
 * resets weights and highlighting;
 * [not yet true] nodes whose position is changed by the sorting are marked
 */
function displayAfterSort( layer, sweepDirection ) {
    setLayerProperty(layer, "color", "cyan");
    if (sweepDirection == "up" ) {
        setChannelProperty(layer - 1, "color", "blue");
        setChannelProperty(layer - 1, "highlight", "true")
    }
    else if (sweepDirection == "down" ) {
        setChannelProperty(layer, "color", "blue");
        setChannelProperty(layer + 1, "highlight", "true")
    }
    displayMessage( layer, sweepDirection );
}

/**
 * changes the weights back to the positions of nodes on a layer and unmarks
 * the nodes that have been marked for position changes; the beginStep
 * matched an endStep after weights are assigned to a new layer
 */
function reset( layer, sweepDirection ) {
    setLayerProperty(layer, "color", "white");
    setLayerProperty(layer, "weightHidden", true);
    setLayerProperty(layer, "marked", false);
    if (sweepDirection == "up" ) {
        setChannelProperty(layer - 1, "color", "black");
        setChannelProperty(layer - 1, "highlight", "false")
    }
    else if (sweepDirection == "down" ) {
        setChannelProperty(layer, "color", "black");
        setChannelProperty(layer + 1, "highlight", "false")
    }
}

/**
 * saves the current positions if the number of crossings has decreased
 */
function checkCrossings() {
    const crossings = totalCrossings();
    if (crossings < minCrossings ) {
        minCrossings = crossings;
        minIteration = iteration;
        minPass = pass;
        // save graph state
        savedPositions = copyNodePositions();
    }
    edgeCrossings = bottleneckCrossings();
    if (edgeCrossings < minEdgeCrossings ) {
        minEdgeCrossings = edgeCrossings;
        minBottleneckIteration = iteration;
        minBottleneckPass = pass;
        //save graph state
        savedBottleneckPositions = copyNodePositions();
    }
}

function upSweep( numLayers ) {
    const sweepDirection = "down";
    for ( let layer = 0; layer < numLayers - 1; layer++ ) {
        step(() => {
            setWeights(layer + 1, "index")
            showIndexes(layer + 1)
            setWeightsDown(layer, "index");
            displayAfterWeightAssignment(layer, sweepDirection);
            evenlySpacedLayout()
        })
        step(() => {
            sortByWeight(layer);
            iteration++;
            checkCrossings();
            displayAfterSort(layer, sweepDirection);
            evenlySpacedLayout()
        })
        step(() => {
            reset(layer, sweepDirection);
            evenlySpacedLayout()
        })
    }
}

function downSweep( numLayers ) {
    const sweepDirection = "up";
    for ( let layer = numLayers - 1; layer >= 1; layer-- ) {
        step(() => {
            setWeights(layer - 1, "index");
            showIndexes(layer - 1);
            setWeightsUp(layer, "index");
            displayAfterWeightAssignment(layer, sweepDirection);
            evenlySpacedLayout()
        })
        step(() => {
            sortByWeight(layer);
            iteration++;
            checkCrossings();
            displayAfterSort(layer, sweepDirection);
            evenlySpacedLayout()
        })
        step(() => {
            reset(layer, sweepDirection);
            evenlySpacedLayout()
        })
    }
}

//Start Barycenter aglorithm

checkCrossings();
while( true ) {
    hideAllNodeWeights();
    pass++;
    upSweep(numLayers);
    downSweep(numLayers);
    let quit = promptBoolean("Do you want to quit? (y/n)");
    if (quit ) {
        break;
    };
}


//display minimum crossing graph
step(() => {
    applyNodePositions(savedPositions);
    display( `min pass = ${minPass}, min iteration = ${minIteration}, min crossings = ${minCrossings} `);
    evenlySpacedLayout()
})

//display minimum bottlneck graph
step(() => {
    applyNodePositions(savedBottleneckPositions);
    display( `min pass = ${minBottleneckPass}, min iteration = ${minBottleneckIteration}, min bottlneck = ${minEdgeCrossings} `);
    evenlySpacedLayout()
})
